import{at as e,it as t,n,vt as r}from"./chunks/framework.BUQROvXk.js";var i=JSON.parse(`{"title":"@jsprismarine/logger","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/logger/index.md","filePath":"api/@jsprismarine/logger/index.md"}`),a={name:`api/@jsprismarine/logger/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../">JSPrismarine</a> / @jsprismarine/logger</p><h1 id="jsprismarine-logger" tabindex="-1">@jsprismarine/logger <a class="header-anchor" href="#jsprismarine-logger" aria-label="Permalink to “@jsprismarine/logger”">​</a></h1><p><a href="https://discord.gg/6w8JWhy" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/704967868885762108?color=%237289DA&amp;label=Discord" alt="Join the Discord Server"></a><a href="https://www.npmjs.com/package/@jsprismarine/logger" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/@jsprismarine/logger" alt="npm"></a></p><p>Leveled logger with a console transport that buffers boot output until a console attaches, plus a plain-text file transport.</p><p>Call <code>logger.isEnabled(level)</code> before formatting an expensive message. It reports whether that level will be written, so hot paths can skip both the message and its arguments when the logger would suppress them.</p><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to “Classes”">​</a></h2><ul><li><a href="./classes/FileTransport.html">FileTransport</a></li><li><a href="./classes/Logger.html">Logger</a></li><li><a href="./classes/PrismarineTransport.html">PrismarineTransport</a></li></ul><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to “Interfaces”">​</a></h2><h3 id="logrecord" tabindex="-1">LogRecord <a class="header-anchor" href="#logrecord" aria-label="Permalink to “LogRecord”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L15" target="_blank" rel="noreferrer">transport.ts:15</a></p><p>One log record as handed to transports: the raw parts plus the line the logger already formatted for terminal output.</p><h4 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h4><h5 id="formatted" tabindex="-1">formatted <a class="header-anchor" href="#formatted" aria-label="Permalink to “formatted”">​</a></h5><blockquote><p><strong>formatted</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L22" target="_blank" rel="noreferrer">transport.ts:22</a></p><p>The colorized console line.</p><h5 id="level" tabindex="-1">level <a class="header-anchor" href="#level" aria-label="Permalink to “level”">​</a></h5><blockquote><p><strong>level</strong>: <code>&quot;error&quot;</code> | <code>&quot;warn&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L16" target="_blank" rel="noreferrer">transport.ts:16</a></p><h5 id="message" tabindex="-1">message <a class="header-anchor" href="#message" aria-label="Permalink to “message”">​</a></h5><blockquote><p><strong>message</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L17" target="_blank" rel="noreferrer">transport.ts:17</a></p><h5 id="namespace" tabindex="-1">namespace <a class="header-anchor" href="#namespace" aria-label="Permalink to “namespace”">​</a></h5><blockquote><p><strong>namespace</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L18" target="_blank" rel="noreferrer">transport.ts:18</a></p><h5 id="timestamp" tabindex="-1">timestamp <a class="header-anchor" href="#timestamp" aria-label="Permalink to “timestamp”">​</a></h5><blockquote><p><strong>timestamp</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L20" target="_blank" rel="noreferrer">transport.ts:20</a></p><p>Wall-clock time as HH:mm:ss.</p><hr><h3 id="logtransport" tabindex="-1">LogTransport <a class="header-anchor" href="#logtransport" aria-label="Permalink to “LogTransport”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L26" target="_blank" rel="noreferrer">transport.ts:26</a></p><p>A destination for log records.</p><h4 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h4><h5 id="close" tabindex="-1">close()? <a class="header-anchor" href="#close" aria-label="Permalink to “close()?”">​</a></h5><blockquote><p><code>optional</code> <strong>close</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L28" target="_blank" rel="noreferrer">transport.ts:28</a></p><h6 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><h5 id="log" tabindex="-1">log() <a class="header-anchor" href="#log" aria-label="Permalink to “log()”">​</a></h5><blockquote><p><strong>log</strong>(<code>record</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L27" target="_blank" rel="noreferrer">transport.ts:27</a></p><h6 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="record" tabindex="-1">record <a class="header-anchor" href="#record" aria-label="Permalink to “record”">​</a></h6><p><a href="#logrecord"><code>LogRecord</code></a></p><h6 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><hr><h3 id="prismarinetransportoptions" tabindex="-1">PrismarineTransportOptions <a class="header-anchor" href="#prismarinetransportoptions" aria-label="Permalink to “PrismarineTransportOptions”">​</a></h3><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L32" target="_blank" rel="noreferrer">transport.ts:32</a></p><p>Options for <a href="./classes/PrismarineTransport.html">PrismarineTransport</a>.</p><h4 id="properties-1" tabindex="-1">Properties <a class="header-anchor" href="#properties-1" aria-label="Permalink to “Properties”">​</a></h4><h5 id="capacity" tabindex="-1">capacity? <a class="header-anchor" href="#capacity" aria-label="Permalink to “capacity?”">​</a></h5><blockquote><p><code>optional</code> <strong>capacity?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L37" target="_blank" rel="noreferrer">transport.ts:37</a></p><p>Most records kept for replay while no console is attached; defaults to 1000. When the buffer is full, the oldest record is dropped first.</p><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h2><h3 id="consolelike" tabindex="-1">ConsoleLike <a class="header-anchor" href="#consolelike" aria-label="Permalink to “ConsoleLike”">​</a></h3><blockquote><p><strong>ConsoleLike</strong> = <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L7" target="_blank" rel="noreferrer">transport.ts:7</a></p><p>The part of a console the transport needs: a sink for one formatted line.</p><h4 id="properties-2" tabindex="-1">Properties <a class="header-anchor" href="#properties-2" aria-label="Permalink to “Properties”">​</a></h4><h5 id="write" tabindex="-1">write <a class="header-anchor" href="#write" aria-label="Permalink to “write”">​</a></h5><blockquote><p><strong>write</strong>: (<code>input</code>) =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/transport.ts#L8" target="_blank" rel="noreferrer">transport.ts:8</a></p><h6 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h6><h6 id="input" tabindex="-1">input <a class="header-anchor" href="#input" aria-label="Permalink to “input”">​</a></h6><p><code>string</code></p><h6 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h6><p><code>void</code></p><hr><h3 id="loglevel" tabindex="-1">LogLevel <a class="header-anchor" href="#loglevel" aria-label="Permalink to “LogLevel”">​</a></h3><blockquote><p><strong>LogLevel</strong> = <em>typeof</em> <a href="#log-levels"><code>LOG_LEVELS</code></a>[<code>number</code>]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/levels.ts#L12" target="_blank" rel="noreferrer">levels.ts:12</a></p><p>A log level.</p><h2 id="variables" tabindex="-1">Variables <a class="header-anchor" href="#variables" aria-label="Permalink to “Variables”">​</a></h2><h3 id="log-levels" tabindex="-1">LOG_LEVELS <a class="header-anchor" href="#log-levels" aria-label="Permalink to “LOG_LEVELS”">​</a></h3><blockquote><p><code>const</code> <strong>LOG_LEVELS</strong>: readonly [<code>&quot;error&quot;</code>, <code>&quot;warn&quot;</code>, <code>&quot;info&quot;</code>, <code>&quot;verbose&quot;</code>, <code>&quot;debug&quot;</code>, <code>&quot;silly&quot;</code>]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/levels.ts#L5" target="_blank" rel="noreferrer">levels.ts:5</a></p><p>Every log level, most severe first. The position is the order a threshold applies: a logger or transport set to <code>info</code> emits <code>error</code>, <code>warn</code>, and <code>info</code> and skips the rest.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><h3 id="isatleastlevel" tabindex="-1">isAtLeastLevel() <a class="header-anchor" href="#isatleastlevel" aria-label="Permalink to “isAtLeastLevel()”">​</a></h3><blockquote><p><strong>isAtLeastLevel</strong>(<code>level</code>, <code>threshold</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/levels.ts#L26" target="_blank" rel="noreferrer">levels.ts:26</a></p><p>Whether <code>level</code> is at least as severe as <code>threshold</code>, so a logger or transport set to <code>threshold</code> emits a record at <code>level</code>. A level passes its own threshold.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="level-1" tabindex="-1">level <a class="header-anchor" href="#level-1" aria-label="Permalink to “level”">​</a></h5><p><code>&quot;error&quot;</code> | <code>&quot;warn&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p><h5 id="threshold" tabindex="-1">threshold <a class="header-anchor" href="#threshold" aria-label="Permalink to “threshold”">​</a></h5><p><code>&quot;error&quot;</code> | <code>&quot;warn&quot;</code> | <code>&quot;info&quot;</code> | <code>&quot;verbose&quot;</code> | <code>&quot;debug&quot;</code> | <code>&quot;silly&quot;</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="isloglevel" tabindex="-1">isLogLevel() <a class="header-anchor" href="#isloglevel" aria-label="Permalink to “isLogLevel()”">​</a></h3><blockquote><p><strong>isLogLevel</strong>(<code>value</code>): value is &quot;error&quot; | &quot;warn&quot; | &quot;info&quot; | &quot;verbose&quot; | &quot;debug&quot; | &quot;silly&quot;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/ab0faca3eeaa6c547f37af024231e14c85b614ac/packages/logger/src/levels.ts#L18" target="_blank" rel="noreferrer">levels.ts:18</a></p><p>Whether a value from a config file or a decoded message names one of <a href="#log-levels">LOG_LEVELS</a>. Matching is exact; <code>INFO</code> is not a level.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="value" tabindex="-1">value <a class="header-anchor" href="#value" aria-label="Permalink to “value”">​</a></h5><p><code>unknown</code></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p>value is &quot;error&quot; | &quot;warn&quot; | &quot;info&quot; | &quot;verbose&quot; | &quot;debug&quot; | &quot;silly&quot;</p>`,102)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};